{"query":"query LobbyHomeTournamentList($groups: [String!]!) {
  tournamentList(type: homepage, limit: 4) {
    fixtureCount(type: homepage)
    ...TournamentTree
    fixtureList(type: homepage, limit: 5, offset: 0) {
      ...FixturePreview
      groups(groups: $groups, status: [active, suspended, deactivated]) {
        ...SportGroupTemplates
      }
    }
