    category {
      sport {
        slug
      }
    }
  }
  data {
    ... on SportFixtureDataMatch {
      competitors {
        name
        abbreviation
      }
      startTime
    }
    ... on SportFixtureDataOutright {
      name
      startTime
    }
  }
}","variables":{"marketId":"2aca77c9-58ec-4a46-912e-f42d44dfb110","provider":"betradar"}}

