          }
          contentNotes {
            ...FixtureNotice_ContentNote
          }
        }
        contentNotes {
          ...FixtureNotice_ContentNote
        }
      }
      contentNotes {
        ...FixtureNotice_ContentNote
      }
    }
    maps: groups(groups: ["maps"]) {
      id
