    matchTime
    remainingTime
  }
  periodScores {
    homeScore
    awayScore
    matchStatus
  }
  currentTeamServing
  homeGameScore
  awayGameScore
  statistic {
    yellowCards {
      away
      home
    }
    redCards {
      away
      home
    }
    corners {
      home
