{"query":"
{
  "heroes": *[
    _type == "hero" 
    && language == $lang
    && isDisplayed != false
    && references(*[_type == 'category' && slug.current == $category]._id)
    && (dateRange.start == null || dateTime(now()) >= dateTime(dateRange.start))
    && (dateRange.end == null || dateTime(now()) <= dateTime(dateRange.end))
    && !(_id in path("drafts.**"))] | order(orderRank)
  {
    _id,
    buttonLink,
    link,
    title,
    description,
    'backgroundImage': {
      'asset': backgroundImage.asset->{url, altText}
    },
    'tag': {
      'name': tag->name,
      'slug': tag->slug.current,
      'icon': tag->icon
    },
    primaryDetails,
    secondaryDetails
  },
  "fallbackHeroes": select(
    $lang != $defaultLanguage => *[
      _type == "hero" 
      && language == $defaultLanguage
      && isDisplayed != false
      && references(*[_type == 'category' && slug.current == $category]._id)
      && (dateRange.start == null || dateTime(now()) >= dateTime(dateRange.start))
      && (dateRange.end == null || dateTime(now()) <= dateTime(dateRange.end))
      && !(_id in path("drafts.**"))] | order(orderRank)
    {
      _id,
      buttonLink,
      link,
      title,
      description,
      'backgroundImage': {
        'asset': backgroundImage.asset->{url, altText}
      },
      'tag': {
        'name': tag->name,
        'slug': tag->slug.current,
        'icon': tag->icon
      },
      primaryDetails,
      secondaryDetails
    },
