{"query":"query HomePageOutrightMarket($marketId: String!, $provider: SportsbookOddsProviderEnum!) {
  sportMarket(marketId: $marketId, provider: $provider) {
    ...HomePageOutrightMarket_SportMarket
  }
}

fragment HomePageOutrightMarket_SportMarket on SportMarket {
  ...SportBetOutcome_SportMarket
  customerCount
  outcomes {
    ...SportBetOutcome_SportMarketOutcome
  }
  fixture {
    ...SportBetOutcome_SportFixture
    slug
    tournament {
      id
      name
      slug
      category {
        id
        name
        slug
      }
    }
  }
}

fragment SportBetOutcome_SportMarket on SportMarket {
  id
  extId
  templateExtId
  name
  status
  specifiers
  customBetAvailable
  provider
}

fragment SportBetOutcome_SportMarketOutcome on SportMarketOutcome {
  id
  active
  odds
  name
  customBetAvailable
}

fragment SportBetOutcome_SportFixture on SportFixture {
  id
  status
  provider
  tournament {
    category {
      sport {
        slug
      }
    }
  }
  data {
    ... on SportFixtureDataMatch {
      competitors {
        name
        abbreviation
      }
      startTime
    }
    ... on SportFixtureDataOutright {
      name
      startTime
    }
  }
}","variables":{"marketId":"2aca77c9-58ec-4a46-912e-f42d44dfb110","provider":"betradar"}}

{"query":"query SportBetTopPicks($sortBy: SportHomepageTrendingOrderByEnum!, $sportId: String) {
  sportHomepageTrendingTopPicks(sortBy: $sortBy, sportId: $sportId) {
    ...Query_SportsHomeTrendingOutcomes
  }
}

fragment Fixture_HomepageTrendingMatches on SportFixture {
  ...FixtureOptions_SportFixture
  ...FixtureOptionsSameGameMultiButton_SportFixture
  ...SportFixtureLiveStreamExists
  slug
  extId
  id
  liveWidgetUrl
  status
  widgetUrl
  data {
    ... on SportFixtureDataMatch {
      __typename
      competitors {
        country
        countryCode
        extId
        iconPath
        name
        abbreviation
      }
      teams {
        name
        qualifier
      }
    }
  }
}

fragment FixtureOptions_SportFixture on SportFixture {
  ...FixtureOptionsOddin_SportFixture
  ...FixtureOptionsBetRadar_SportFixture
}

fragment FixtureOptionsOddin_SportFixture on SportFixture {
  id
  extId
  name
  provider
  status
  widgetUrl
  liveWidgetUrl
  tournament {
    slug
    frontRowSeatEvent {
      identifier
    }
    category {
      slug
      sport {
        slug
      }
    }
  }
  data {
    ... on SportFixtureDataMatch {
      competitors {
        name
        abbreviation
      }
      tvChannels {
        name
        streamUrl
        language
      }
      startTime
    }
    ... on SportFixtureDataOutright {
      name
      startTime
    }
  }
}

fragment FixtureOptionsBetRadar_SportFixture on SportFixture {
  id
  extId
  name
  provider
  status
  widgetUrl
  liveWidgetUrl
  betradarStream {
    exists
  }
  liveStream {
    data {
      isAvailable
    }
  }
  frontRowSeatFight {
    fightId
  }
  tournament {
    slug
    frontRowSeatEvent {
      identifier
    }
    category {
      slug
      sport {
        slug
      }
    }
  }
  data {
    ... on SportFixtureDataMatch {
      competitors {
        name
        abbreviation
      }
      tvChannels {
        name
        streamUrl
        language
      }
      startTime
    }
    ... on SportFixtureDataOutright {
      name
      startTime
    }
  }
}

fragment FixtureOptionsSameGameMultiButton_SportFixture on SportFixture {
  sgmAvailable: customBetAvailable
  swish: swishGame {
    sport: swishSport {
      sgmAvailable: customBetAvailable
      sgmLiveAvailable: liveCustomBetAvailable
    }
  }
}

fragment SportFixtureLiveStreamExists on SportFixture {
  id
  betradarStream {
    exists
  }
  liveStream {
    data {
      isAvailable
    }
  }
}

fragment Outcome_OutcomesWithBetCount on SportMarketOutcome {
  active
  customBetAvailable
  extId
  id
  name
  odds
  payout
  probabilities
  provider
  voidFactor
}

fragment Query_SportsHomeTrendingOutcomes on SportHomepageTrendingOutcomes {
  statistics {
    totalBetValue
    totalUserCount
  }
  outcome {
    ... on SportMarketOutcome {
      id
      name
      market {
        ...Market_TopOutcomeMarket
      }
    }
  }
}

fragment Market_TopOutcomeMarket on SportMarket {
  extId
  templateExtId
  id
  name
  provider
  rank
  specifiers
  status
  enabled
  customBetAvailable
  extendedSpecifiers
  outcomes {
    ...Outcome_OutcomesWithBetCount
  }
  fixture {
    ...Fixture_HomepageTrendingMatches
  }
}","variables":{"sortBy":"totalBetValue"}}

{"query":"query SportBetTrendingMatches($sortBy: SportHomepageTrendingOrderByEnum!, $groups: [String!], $templatesLimit: Int!, $sportId: String) {
  sportHomepageTrendingMatches(sortBy: $sortBy, sportId: $sportId) {
    ...Query_HomepageTrendingMatches
  }
