requestBody:
{"query":"query SportAllGroups($sport: String!) {
  slugSport(sport: $sport) {
    id
    allGroups {
      name
      translation
      rank
      id
    }
  }
}","variables":{"sport":"tennis"}}

{"query":"query SportBreadcrumb($sport: String!) {
  slugSport(sport: $sport) {
    id
    name
    slug
  }
}","variables":{"sport":"tennis"}}

{"query":"query SportIndex($sport: String!, $group: String!, $type: SportSearchEnum = popular) {
  slugSport(sport: $sport) {
    id
    name
    templates(group: $group) {
      id
      name
      extId
    }
    firstTournament: tournamentList(type: $type, limit: 1) {
      id
      name
      slug
      category {
        id
        slug
        name
        countryCode
      }
      fixtureCount(type: $type)
      fixtureList(type: $type, limit: 10) {
        ...FixturePreview
        ...UfcFrontRowSeat
        groups(groups: [$group], status: [active, suspended, deactivated]) {
          ...SportGroupTemplates
        }
      }
    }
    tournamentList(type: $type, limit: 5) {
      id
      name
      slug
      fixtureCount(type: $type)
      category {
        id
        slug
        name
        countryCode
      }
    }
    categoryList(type: $type, limit: 100) {
      id
      slug
      name
      countryCode
      fixtureCount(type: $type)
      tournamentList(type: $type, limit: 100) {
        id
        slug
        name
        fixtureCount(type: $type)
        category {
          id
          slug
          name
          countryCode
        }
      }
    }
  }
}

fragment FixturePreview on SportFixture {
  id
  ...SportFixtureLiveStreamExists
  ...FixtureOptionsSameGameMultiButton_SportFixture
  status
  slug
  name
  provider
  marketCount(status: [active, suspended])
  extId
  liveWidgetUrl
  widgetUrl
  data {
    __typename
    ...SportFixtureDataMatch
    ...SportFixtureDataOutright
  }
  tournament {
    ...TournamentTreeNested
  }
  eventStatus {
    ...SportFixtureEventStatus
    ...EsportFixtureEventStatus
  }
}

fragment SportFixtureLiveStreamExists on SportFixture {
  id
  betradarStream {
    exists
  }
  liveStream {
    data {
      isAvailable
    }
  }
}

fragment FixtureOptionsSameGameMultiButton_SportFixture on SportFixture {
  sgmAvailable: customBetAvailable
  swish: swishGame {
    sport: swishSport {
      sgmAvailable: customBetAvailable
      sgmLiveAvailable: liveCustomBetAvailable
    }
  }
}

fragment SportFixtureDataMatch on SportFixtureDataMatch {
  startTime
  isOutright
  competitors {
    ...SportFixtureCompetitor
  }
  teams {
    name
    qualifier
  }
  tvChannels {
    language
    name
    streamUrl
  }
  __typename
}

fragment SportFixtureCompetitor on SportFixtureCompetitor {
  name
  defaultName
  extId
  countryCode
  abbreviation
  iconPath
}

fragment SportFixtureDataOutright on SportFixtureDataOutright {
  isOutright
  name
  startTime
  endTime
  __typename
}

fragment TournamentTreeNested on SportTournament {
  id
  name
  slug
  category {
    ...CategoryTreeNested
    cashoutEnabled
  }
}

fragment CategoryTreeNested on SportCategory {
  id
  name
  slug
  sport {
    id
    name
    slug
  }
}

fragment SportFixtureEventStatus on SportFixtureEventStatusData {
  __typename
  homeScore
  awayScore
  matchStatus
  clock {
    matchTime
    remainingTime
  }
  periodScores {
    homeScore
    awayScore
    matchStatus
  }
  currentTeamServing
  homeGameScore
  awayGameScore
  statistic {
    yellowCards {
      away
      home
    }
    redCards {
      away
      home
    }
    corners {
      home
      away
    }
  }
}

fragment EsportFixtureEventStatus on EsportFixtureEventStatus {
  matchStatus
  homeScore
  awayScore
  scoreboard {
    homeGold
    awayGold
    homeGoals
    awayGoals
    homeKills
    awayKills
    gameTime
    homeDestroyedTowers
    awayDestroyedTowers
    homeDestroyedTurrets
    awayDestroyedTurrets
    currentRound
    currentCtTeam
    currentDefTeam
    time
    awayWonRounds
    homeWonRounds
    remainingGameTime
  }
  periodScores {
    type
    number
    awayGoals
    awayKills
    awayScore
    homeGoals
    homeKills
    homeScore
    awayWonRounds
    homeWonRounds
    matchStatus
  }
  __typename
}

fragment UfcFrontRowSeat on SportFixture {
  frontRowSeatFight {
    fightId
  }
  tournament {
    frontRowSeatEvent {
      identifier
    }
  }
}

fragment SportGroupTemplates on SportGroup {
  ...SportGroup
  templates(limit: 10, includeEmpty: true) {
    ...SportGroupTemplate
    markets(limit: 1) {
      ...SportMarket
      outcomes {
        ...SportMarketOutcome
      }
    }
  }
}

fragment SportGroup on SportGroup {
  name
  translation
  rank
}

fragment SportGroupTemplate on SportGroupTemplate {
  extId
  rank
  name
}

fragment SportMarket on SportMarket {
  id
  name
  status
  extId
  specifiers
  customBetAvailable
  provider
  templateExtId
}

fragment SportMarketOutcome on SportMarketOutcome {
  __typename
  id
  active
  odds
  name
  customBetAvailable
}","variables":{"sport":"tennis","group":"winner"}}

{"query":"query SportBetDailyTopMultis {
  sportCuratedDailyMultiSet {
    id
    name
    status
    multis {
      id
      name
      status
      displayOrder
      totalUserCount
      legs {
        id
        displayOrder
        outcome {
          id
          name
          odds
          active
          provider
          market {
            id
            name
            status
            provider
            extId
            fixture {
              ...FixtureStatus_SportFixture
              id
              status
              provider
              slug
              tournament {
                slug
                category {
                  slug
                  sport {
                    slug
                  }
                }
              }
              data {
                __typename
                ... on SportFixtureDataMatch {
                  startTime
                  competitors {
                    name
                    countryCode
                    extId
                    iconPath
                    country
                    abbreviation
                  }
                  teams {
                    name
                    qualifier
                  }
                }
                ... on SportFixtureDataOutright {
                  name
                  startTime
                }
              }
            }
          }
        }
      }
    }
  }
}

fragment FixtureStatus_SportFixture on SportFixture {
  id
  status
  ...FixtureOptions_SportFixture
  ...Live_SportFixture
  ...Active_SportFixture
}

fragment FixtureOptions_SportFixture on SportFixture {
  ...FixtureOptionsOddin_SportFixture
  ...FixtureOptionsBetRadar_SportFixture
}

fragment FixtureOptionsOddin_SportFixture on SportFixture {
  id
  extId
  name
  provider
  status
  widgetUrl
  liveWidgetUrl
  tournament {
    slug
    frontRowSeatEvent {
      identifier
    }
    category {
      slug
      sport {
        slug
      }
    }
  }
  data {
    ... on SportFixtureDataMatch {
      competitors {
        name
        abbreviation
      }
      tvChannels {
        name
        streamUrl
        language
      }
      startTime
    }
    ... on SportFixtureDataOutright {
      name
      startTime
    }
  }
}

fragment FixtureOptionsBetRadar_SportFixture on SportFixture {
  id
  extId
  name
  provider
  status
  widgetUrl
  liveWidgetUrl
  betradarStream {
    exists
  }
  liveStream {
    data {
      isAvailable
    }
  }
  frontRowSeatFight {
    fightId
  }
  tournament {
    slug
    frontRowSeatEvent {
      identifier
    }
    category {
      slug
      sport {
        slug
      }
    }
  }
  data {
    ... on SportFixtureDataMatch {
      competitors {
        name
        abbreviation
      }
      tvChannels {
        name
        streamUrl
        language
      }
      startTime
    }
    ... on SportFixtureDataOutright {
      name
      startTime
    }
  }
}

fragment Live_SportFixture on SportFixture {
  provider
  eventStatus {
    ... on SportFixtureEventStatusData {
      matchStatus
      periodScores {
        matchStatus
      }
      clock {
        matchTime
        remainingTime
      }
    }
    ... on EsportFixtureEventStatus {
      matchStatus
      periodScores {
        matchStatus
      }
      scoreboard {
        gameTime
        remainingGameTime
      }
    }
  }
  tournament {
    category {
      sport {
        slug
      }
    }
  }
}

fragment Active_SportFixture on SportFixture {
  data {
    ... on SportFixtureDataOutright {
      endTime
    }
    ... on SportFixtureDataMatch {
      startTime
    }
  }
}","variables":{}}

{"query":"query SportTournamentFixtureList($sport: String!, $groups: String!, $tournamentLimit: Int = 25, $fixtureCountLimit: Int = 20, $type: SportSearchEnum!) {
  slugSport(sport: $sport) {
    id
    name
    templates(group: $groups) {
      id
      name
      extId
    }
    tournamentList(type: $type, limit: $tournamentLimit) {
      ...TournamentTree
      fixtureCount(type: $type)
      fixtureList(type: $type, limit: $fixtureCountLimit) {
        ...FixturePreview
        ...UfcFrontRowSeat
        groups(groups: [$groups], status: [active, suspended, deactivated]) {
          ...SportGroupTemplates
        }
      }
    }
  }
}

fragment TournamentTree on SportTournament {
  id
  name
  slug
  category {
    ...CategoryTree
  }
}

fragment CategoryTree on SportCategory {
  id
  name
  slug
  sport {
    id
    name
    slug
  }
}

fragment FixturePreview on SportFixture {
  id
  ...SportFixtureLiveStreamExists
  ...FixtureOptionsSameGameMultiButton_SportFixture
  status
  slug
  name
  provider
  marketCount(status: [active, suspended])
  extId
  liveWidgetUrl
  widgetUrl
  data {
    __typename
    ...SportFixtureDataMatch
    ...SportFixtureDataOutright
  }
  tournament {
    ...TournamentTreeNested
  }
  eventStatus {
    ...SportFixtureEventStatus
    ...EsportFixtureEventStatus
  }
}

fragment SportFixtureLiveStreamExists on SportFixture {
  id
  betradarStream {
    exists
  }
  liveStream {
    data {
      isAvailable
    }
  }
}

fragment FixtureOptionsSameGameMultiButton_SportFixture on SportFixture {
  sgmAvailable: customBetAvailable
  swish: swishGame {
    sport: swishSport {
      sgmAvailable: customBetAvailable
      sgmLiveAvailable: liveCustomBetAvailable
    }
  }
}

fragment SportFixtureDataMatch on SportFixtureDataMatch {
  startTime
  isOutright
  competitors {
    ...SportFixtureCompetitor
  }
  teams {
    name
    qualifier
  }
  tvChannels {
    language
    name
    streamUrl
  }
  __typename
}

fragment SportFixtureCompetitor on SportFixtureCompetitor {
  name
  defaultName
  extId
  countryCode
  abbreviation
  iconPath
}

fragment SportFixtureDataOutright on SportFixtureDataOutright {
  isOutright
  name
  startTime
  endTime
  __typename
}

fragment TournamentTreeNested on SportTournament {
  id
  name
  slug
  category {
    ...CategoryTreeNested
    cashoutEnabled
  }
}

fragment CategoryTreeNested on SportCategory {
  id
  name
  slug
  sport {
    id
    name
    slug
  }
}

fragment SportFixtureEventStatus on SportFixtureEventStatusData {
  __typename
  homeScore
  awayScore
  matchStatus
  clock {
    matchTime
    remainingTime
  }
  periodScores {
    homeScore
    awayScore
    matchStatus
  }
  currentTeamServing
  homeGameScore
  awayGameScore
  statistic {
    yellowCards {
      away
      home
    }
    redCards {
      away
      home
    }
    corners {
      home
      away
    }
  }
}

fragment EsportFixtureEventStatus on EsportFixtureEventStatus {
  matchStatus
  homeScore
  awayScore
  scoreboard {
    homeGold
    awayGold
    homeGoals
    awayGoals
    homeKills
    awayKills
    gameTime
    homeDestroyedTowers
    awayDestroyedTowers
    homeDestroyedTurrets
    awayDestroyedTurrets
    currentRound
    currentCtTeam
    currentDefTeam
    time
    awayWonRounds
    homeWonRounds
    remainingGameTime
  }
  periodScores {
    type
    number
    awayGoals
    awayKills
    awayScore
    homeGoals
    homeKills
    homeScore
    awayWonRounds
    homeWonRounds
    matchStatus
  }
  __typename
}

fragment UfcFrontRowSeat on SportFixture {
  frontRowSeatFight {
    fightId
  }
  tournament {
    frontRowSeatEvent {
      identifier
    }
  }
}

fragment SportGroupTemplates on SportGroup {
  ...SportGroup
  templates(limit: 10, includeEmpty: true) {
    ...SportGroupTemplate
    markets(limit: 1) {
      ...SportMarket
      outcomes {
        ...SportMarketOutcome
      }
    }
  }
}

fragment SportGroup on SportGroup {
  name
  translation
  rank
}

fragment SportGroupTemplate on SportGroupTemplate {
  extId
  rank
  name
}

fragment SportMarket on SportMarket {
  id
  name
  status
  extId
  specifiers
  customBetAvailable
  provider
  templateExtId
}

fragment SportMarketOutcome on SportMarketOutcome {
  __typename
  id
  active
  odds
  name
  customBetAvailable
