_key":"ae9b8124f442","_type":"block","asset":null,"children":[{"_key":"fee4e1dca095","_type":"span","marks":[],"text":"Santa Clara, California - Levi’s Stadium"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"9ec360642ce8","_type":"block","asset":null,"children":[{"_key":"5884069d6e6d","_type":"span","marks":[],"text":"Los Angeles, California - SoFi Stadium"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"1308ca65016c","_type":"block","asset":null,"children":[{"_key":"c069a6796da7","_type":"span","marks":[],"text":"Philadelphia, Pennsylvania - Lincoln Financial Field"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"b98604835060","_type":"block","asset":null,"children":[{"_key":"90ef76dd67d6","_type":"span","marks":[],"text":"Seattle, Washington - Lumen Field"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"33d2732e6d1c","_type":"block","asset":null,"children":[{"_key":"95b1e6c720e8","_type":"span","marks":[],"text":"Boston, Massachusetts - Gillette Stadium"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"cf79c7bd37e6","_type":"block","asset":null,"children":[{"_key":"a13d3440e78f","_type":"span","marks":[],"text":"Miami, Florida - Hard Rock Stadium"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"2f2b1b2dd2bc","_type":"block","asset":null,"children":[{"_key":"8a1f53f3082e","_type":"span","marks":[],"text":"Vancouver, Canada - BC Place"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"519acc8047ae","_type":"block","asset":null,"children":[{"_key":"da19b2451028","_type":"span","marks":[],"text":"Monterrey, Mexico - Estadio BBVA"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"3e9f33bc923e","_type":"block","asset":null,"children":[{"_key":"eb2c71a080f2","_type":"span","marks":[],"text":"Guadalajara, Mexico - Estadio Akron"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"5792cd321bea","_type":"block","asset":null,"children":[{"_key":"9d989949b312","_type":"span","marks":[],"text":"Toronto, Canada - BMO Field"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"88c371b357ae","_type":"block","asset":null,"children":[{"_key":"369e278c5d63","_type":"span","marks":[],"text":"The final of the 2026 tournament takes place at the MetLife Stadium in New Jersey, US."}],"markDefs":[],"style":"normal"},{"_key":"d44854e153b8","_type":"block","asset":null,"children":[{"_key":"34b266f5b100","_type":"span","marks":[],"text":"How the new 48-team format works"}],"markDefs":[],"style":"h2"},{"_key":"e6f9cffa852b","_type":"block","asset":null,"children":[{"_key":"062428e0e80d","_type":"span","marks":[],"text":"48 teams are split between 12 groups of 4. Teams face each of their group opponents once, and the top 2 teams qualify for the first round of the knockout stages. Joining them will be the 8 best third-place teams."}],"markDefs":[],"style":"normal"},{"_key":"d03dec30e8cf","_type":"block","asset":null,"children":[{"_key":"efff5e27fb95","_type":"span","marks":[],"text":"From 32 to 48 teams: groups, the Round of 32, and what changed"}],"markDefs":[],"style":"h3"},{"_key":"cd015adbb20a","_type":"block","asset":null,"children":[{"_key":"3c78447e02c2","_type":"span","marks":[],"text":"While the format has been expanded, the group stage remains more or less the same. Teams will still be drawn randomly into groups of 4, but now there are 12 groups rather than 8."}],"markDefs":[],"style":"normal"},{"_key":"9aab1ce87c7c","_type":"block","asset":null,"children":[{"_key":"76c2c7260067","_type":"span","marks":[],"text":"The expanded format means that teams will now play up to 8 matches over the course of the tournament, with a new round added to the knockout stage. The round of 32 will now be the first knockout stage following the groups."}],"markDefs":[],"style":"normal"},{"_key":"e830bd79bc2c","_type":"block","asset":null,"children":[{"_key":"0e7453956499","_type":"span","marks":[],"text":"How the expanded format affects betting strategy"}],"markDefs":[],"style":"h3"},{"_key":"e14a2ea51e3a","_type":"block","asset":null,"children":[{"_key":"03733f3d52ba","_type":"span","marks":[],"text":"The new format with a greater number of teams means that there will probably be fewer shock results during the first stage. Higher-ranked teams will have a greater chance of progressing, especially as the 8 best third-placed teams will now advance to the knockout stage."}],"markDefs":[],"style":"normal"},{"_key":"dd0bae9013d4","_type":"block","asset":null,"children":[{"_key":"67db7573c022","_type":"span","marks":[],"text":"The expanded format also means more lower-ranked teams are taking part. This could result in higher-scoring games when lower-ranked teams face a stronger team. This means there are opportunities for betting on the over line for total goals in these matches."}],"markDefs":[],"style":"normal"},{"_key":"3fbde2b2ea83","_type":"block","asset":null,"children":[{"_key":"52347a4a0396","_type":"span","marks":[],"text":"Group-by-group betting preview"}],"markDefs":[],"style":"h2"},{"_key":"6b7ad2b93047","_type":"block","asset":null,"children":[{"_key":"834aa8a4e4b6","_type":"span","marks":[],"text":"Here are the current odds for each of the 12 groups at this tournament:"}],"markDefs":[],"style":"normal"},{"_key":"87472375db69","_type":"block","asset":null,"children":[{"_key":"56eb9a2f1dc7","_type":"span","marks":[],"text":"Group A - Mexico is the favourite to advance, with Czechia and the Republic of Korea fighting for 2nd place while South Africa is an outsider."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"2da8507106c5","_type":"block","asset":null,"children":[{"_key":"a1c57db6e2db","_type":"span","marks":[],"text":"Group B - Switzerland is the most likely to progress to the next round ahead of Canada and Bosnia and Herzegovina. Qatar is likely to finish last."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"79124ff93deb","_type":"block","asset":null,"children":[{"_key":"747ca8b8a9a8","_type":"span","marks":[],"text":"Group C - Brazil are massive favourites to win the group, with Morocco most likely in second. Scotland has an outside chance of qualifying, while Haiti are extremely unfavoured."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"db699fb87426","_type":"block","asset":null,"children":[{"_key":"78e7cefa7b88","_type":"span","marks":[],"text":"Group D - Host country USA has a good chance of qualifying, but it’s close between them and Turkey. Paraguay are also a tough opponent, but Australia are unlikely to go through."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"96c3e3e3ac25","_type":"block","asset":null,"children":[{"_key":"2156f2bb338b","_type":"span","marks":[],"text":"Group E - Germany are big favourites to qualify for the round of 32 ahead of Ecuador, while Ivory Coast and Curaçao are predicted to finish in 3rd and 4th."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"e919e0cab198","_type":"block","asset":null,"children":[{"_key":"ca2395768b1a","_type":"span","marks":[],"text":"Group F - Netherlands haven’t won the tournament before, but they’re expected to win their group. Japan are a tough opponent though, and Sweden have looked strong at times during qualifying. Tunisia are also a difficult opponent, but not expected to go through."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"cf88188a398a","_type":"block","asset":null,"children":[{"_key":"8dfbbcc809d8","_type":"span","marks":[],"text":"Group G - Belgium have a clear path to the knockout round and should finish ahead of Egypt, Iran and New Zealand."}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"f58fd2da85b1","_type":"block","asset":null,"children":[{"_key":"1a82b15b86a9","_type":"span","marks":[],"