fragment BetsBoardSport_BetBetHero on BetBet {
  ...BetsBoardSport_BetBetBase
  ... on SwishBet {
    outcomes {
      id
      lineType
      outcome {
        id
        name
        line
        over
        under
        push
        suspended
        market {
          id
          stat {
            swishStatId
            name
            type
          }
          data {
            atBat {
              marketDurationStart
              half
              inning
              pitcherName
            }
          }
          competitor {
            name
          }
          game {
            id
            fixture {
              id
              swishGame {
                status
                swishSportId
              }
              data {
                ... on SportFixtureDataMatch {
                  competitors {
                    name
                    abbreviation
                  }
                }
                ... on SportFixtureDataOutright {
                  name
                }
              }
              tournament {
                slug
                category {
                  sport {
                    slug
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  ... on SportBet {
    outcomes {
      id
      odds
      fixtureAbreviation
      fixtureName
      outcome {
        id
        odds
        name
      }
      market {
        id
        name
        status
      }
      fixture {
        id
        status
        provider
        data {
          ... on SportFixtureDataMatch {
            competitors {
              name
              abbreviation
            }
          }
          ... on SportFixtureDataOutright {
            name
          }
        }
        tournament {
          slug
          category {
            sport {
              slug
            }
          }
        }
      }
    }
  }
}

fragment BetsBoardSport_BetBetBase on BetBet {
  __typename
  ... on SwishBet {
    __typename
    id
    customBet
    updatedAt
    createdAt
    potentialMultiplier
    amount
    currency
    user {
      id
      name
      preferenceHideBets
    }
    outcomes {
      __typename
      id
      odds
      outcome {
        __typename
        id
        market {
          id
          competitor {
            name
          }
          game {
            id
            fixture {
              id
              tournament {
                id
                category {
                  id
                  sport {
                    id
                    slug
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  ... on SportBet {
    __typename
    id
    customBet
    updatedAt
    createdAt
    potentialMultiplier
    amount
    currency
    user {
      name
      preferenceHideBets
    }
    outcomes {
      id
      odds
      fixtureAbreviation
      fixtureName
      fixture {
        id
        tournament {
          id
          slug
          category {
            id
            sport {
              id
              slug
            }
          }
        }
      }
    }
  }
  ... on RacingBet {
    __typename
    id
    active
    payout
    updatedAt
    createdAt
    betPotentialMultiplier: potentialMultiplier
    amount
    currency
    betStatus: status
    payoutMultiplier
    adjustments {
      payoutMultiplier
    }
    user {
      id
      name
      preferenceHideBets
    }
    outcomes {
      id
      type
      derivativeType
      prices {
        marketName
        odds
      }
      event {
        meeting {
          racing {
            slug
          }
        }
      }
      selectionSlots {
        runners {
          name
        }
      }
      result {
        resultedPrices
      }
    }
  }
}","variables":{"tournamentSlug":"soccer/international/world-cup"}}

{"query":"query TournamentBreadcrumb($sport: String!, $category: String!, $tournament: String!) {
