{"query":"query GetMyMultiBoostSportPromotion($experimentPromotionId: String) {
  getMyMultiBoostSportPromotion(experimentPromotionId: $experimentPromotionId) {
    ...SportPromotionFragment
  }
}

fragment SportPromotionFragment on SportsPromotion {
  id
  isTargeted
  vipLevel
  betType
  description
  category: betCategory
  startsAt: startDate
  endsAt: endDate
  name
  type {
    code
  }
  specifiers {
    provider
    level: identifierEnum
    line
    lineType
    outcome {
      id
      extId
      name
    }
    stat {
      id
      name
    }
    market {
      ... on SportMarket {
        id
        extId
        templateExtId
        specifiers
        name
      }
      ... on SwishSportStat {
        id
        name
      }
    }
    competitor {
      ... on SwishCompetitor {
        id
        name
      }
    }
    data: identifier {
      ... on SwishSport {
        id
        slug
      }
      ... on Sport {
        id
        slug
      }
      ... on SportCategory {
        id
        slug
      }
      ... on SportTournament {
        id
        slug
      }
      ... on SportFixture {
        id
      }
      ... on SwishGame {
        id
        teams {
          name
        }
      }
    }
  }
  rule {
    min: minBet
    max: maxBet
    conditions {
      value
      tf: promotionTypeField {
        field {
          code
        }
      }
    }
    boostLadder {
      boost
      legs
    }
  }
}","variables":{}}

